From f1ff29617e8c3a5d4d89c3aed5a48aaba2df05ae Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:04:55 +0100
Subject: [PATCH] folder: update all desktops right away when moving icons
 between screens

When icons were dropped on another screen, their new screen was only
announced after a 100 ms delay, so the source screen briefly showed them
again at their old place. The mapping change is now sent immediately.

BUG: 482572
---
 containments/desktop/plugins/folder/foldermodel.cpp | 4 +++-
 1 file changed, 3 insertions(+), 1 deletion(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..4778e11ec5 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -1392,7 +1392,9 @@ void FolderModel::drop(QQuickItem *target, QObject *dropEvent, int row, bool sho
             const QList<QUrl> urls = mimeData->urls();
             for (const auto &url : urls) {
                 m_dropTargetPositions.insert(url.fileName(), dropPos);
-                m_screenMapper->addMapping(mappableUrl(url), m_screen, m_currentActivity, ScreenMapper::DelayedSignal);
+                // Signal the last one right away so the source view hides the items before the drag ends and unblanks them
+                const auto behavior = url == urls.constLast() ? ScreenMapper::ImmediateSignal : ScreenMapper::DelayedSignal;
+                m_screenMapper->addMapping(mappableUrl(url), m_screen, m_currentActivity, behavior);
                 m_screenMapper->removeItemFromDisabledScreen(mappableUrl(url));
             }
             m_dropTargetPositionsCleanup->start();
